1	import 'dart:convert';
2	
3	import 'package:dio/dio.dart';
4	import 'package:flutter/services.dart';
5	import 'package:flutter_dotenv/flutter_dotenv.dart';
6	import 'package:flutter_test/flutter_test.dart';
7	import 'package:hive_ce/hive_ce.dart';
8	import 'package:path_provider_platform_interface/path_provider_platform_interface.dart';
9	
10	import 'package:cerne/core/di/injection_container.dart';
11	import 'package:cerne/core/network/access_token_provider.dart';
12	import 'package:cerne/core/network/url_builder.dart';
13	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
14	import 'package:cerne/features/chat/presentation/cubit/chat_cubit.dart';
15	import 'package:cerne/features/chat/presentation/cubit/chat_state.dart';
16	
17	import '../../support/fake_path_provider_platform.dart';
18	
19	/// Same shape as `capture_flow_e2e_test.dart`'s/`entry_detail_flow_e2e_
20	/// test.dart`'s own fake adapter, extended with [queueSseResponse] for
21	/// `ApiClient.postStream`'s `ResponseType.stream` requests — only the
22	/// transport boundary is faked.
23	///
24	/// A queued SSE response is delivered as the exact [chunks] given, each
25	/// its own separate stream emission (never pre-joined into one string) —
26	/// this is what proves `ChatRemoteDataSource.sendMessage`'s own
27	/// `\n\n`-boundary buffering really works across genuine network chunk
28	/// boundaries, not just against a single already-complete event.
29	class _FakeHttpClientAdapter implements HttpClientAdapter {
30	  final List<RequestOptions> requests = [];
31	  final List<ResponseBody Function()> _queue = [];
32	
33	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
34	    _queue.add(
35	      () => ResponseBody.fromString(
36	        jsonEncode(body),
37	        statusCode,
38	        headers: {
39	          Headers.contentTypeHeader: [Headers.jsonContentType],
40	        },
41	      ),
42	    );
43	  }
44	
45	  void queueErrorResponse(String code, String message, {int statusCode = 503}) {
46	    queueJsonResponse(statusCode, {
47	      'code': code,
48	      'message': message,
49	      'retryable': true,
50	    });
51	  }
52	
53	  void queueSseResponse(List<String> chunks, {int statusCode = 200}) {
54	    _queue.add(
55	      () => ResponseBody(
56	        Stream.fromIterable(
57	          chunks.map((chunk) => Uint8List.fromList(utf8.encode(chunk))),
58	        ),
59	        statusCode,
60	        headers: {
61	          Headers.contentTypeHeader: ['text/event-stream'],
62	        },
63	      ),
64	    );
65	  }
66	
67	  @override
68	  Future<ResponseBody> fetch(
69	    RequestOptions options,
70	    Stream<Uint8List>? requestStream,
71	    Future<void>? cancelFuture,
72	  ) async {
73	    requests.add(options);
74	    if (_queue.isEmpty) {
75	      throw StateError(
76	        'No queued response for ${options.method} ${options.path}',
77	      );
78	    }
79	    return _queue.removeAt(0)();
80	  }
81	
82	  @override
83	  void close({bool force = false}) {}
84	}
85	
86	Map<String, dynamic> _sessionJson({required String id, required String updatedAt}) => {
87	  'id': id,
88	  'title': 'Nova conversa',
89	  'personaSnapshot': 'empatico',
90	  'userMessageCount': 0,
91	  'lastUserMessageAt': null,
92	  'createdAt': updatedAt,
93	  'updatedAt': updatedAt,
94	};
95	
96	/// End-to-end coverage for spec-6-1's chat flow, driven through the real
97	/// production object graph `sl` resolves for Home/Chat (the exact
98	/// `ChatCubit` instance `app_router.dart` gives `ChatScreen`), wired to
99	/// the real `ChatRepositoryImpl` -> `ChatRemoteDataSource` -> `ApiClient`
100	/// -> `Dio` (both real interceptors attached) -> the real `chat_sessions`/
101	/// `chat_messages` Hive boxes. Only the transport boundary and the native
102	/// plugins (secure storage, path_provider) are faked — no device/
103	/// simulator/CI exists yet (AGENTS.md).
104	///
105	/// Complements rather than duplicates this story's existing mocked tests
106	/// (`chat_cubit_test.dart` against a fake `ChatRepository`,
107	/// `chat_repository_impl_test.dart`/`chat_remote_data_source_test.dart`
108	/// against a mocked `ApiClient`): none of them drives a real SSE byte
109	/// stream through the real `ApiClient.postStream` -> `ChatRemoteDataSource`
110	/// `\n\n`-buffering -> `ChatCubit` token-append pipeline in one send, the
111	/// way the app actually does on every message.
112	///
113	/// Driven directly against `ChatCubit`'s own public API (`init`/
114	/// `sendMessage`), not through `tester.tap`/`pumpAndSettle` — same
115	/// rationale `capture_flow_e2e_test.dart` documents: these awaits span
116	/// genuine async I/O (a real Dio round trip over a faked transport), and
117	/// `pumpAndSettle` isn't guaranteed to wait for that.
118	void main() {
119	  TestWidgetsFlutterBinding.ensureInitialized();
120	
121	  const secureStorageChannel = MethodChannel(
122	    'plugins.it_nomads.com/flutter_secure_storage',
123	  );
124	  final fakeNativeStorage = <String, String>{};
125	
126	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
127	    final args = call.arguments as Map<dynamic, dynamic>;
128	    switch (call.method) {
129	      case 'write':
130	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
131	        return null;
132	      case 'read':
133	        return fakeNativeStorage[args['key'] as String];
134	      case 'delete':
135	        fakeNativeStorage.remove(args['key'] as String);
136	        return null;
137	      case 'containsKey':
138	        return fakeNativeStorage.containsKey(args['key'] as String);
139	      default:
140	        return null;
141	    }
142	  }
143	
144	  late FakePathProviderPlatform fakePathProvider;
145	  late _FakeHttpClientAdapter adapter;
146	
147	  setUp(() async {
148	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
149	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
150	    fakePathProvider = FakePathProviderPlatform();
151	    PathProviderPlatform.instance = fakePathProvider;
152	
153	    await resetCoreDependencies();
154	    await setupCoreDependencies();
155	
156	    adapter = _FakeHttpClientAdapter();
157	    sl<Dio>().httpClientAdapter = adapter;
158	
159	    // `chat-messages-send` et al. are bearer-required operations — seed a
160	    // user access token through the real `AccessTokenProvider` so the
161	    // real header interceptor has one to send.
162	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
163	  });
164	
165	  tearDown(() async {
166	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
167	        .setMockMethodCallHandler(secureStorageChannel, null);
168	    fakeNativeStorage.clear();
169	    await Hive.close();
170	    await resetCoreDependencies();
171	    await fakePathProvider.cleanUp();
172	  });
173	
174	  test(
175	    'happy path: no existing session -> bootstrap creates one, then '
176	    'sendMessage() drives a genuine multi-chunk SSE POST to '
177	    'chat-messages-send/{sessionId} through the real pipeline, joining '
178	    'tokens split across chunk boundaries into one complete AI bubble',
179	    () async {
180	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
181	      adapter.queueJsonResponse(200, {
182	        'data': _sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z'),
183	      });
184	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
185	      adapter.queueSseResponse([
186	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n',
187	        // Split mid-event: this chunk ends inside an incomplete token
188	        // event's `data:` line, the next one finishes it and immediately
189	        // opens a second event in the same chunk.
190	        'event: token\ndata: {"delta":"Ol',
191	        'á, tudo bem?"}\n\nevent: token\ndata: {"delta":" Vamos conversar."}\n\n',
192	        'event: done\ndata: {}\n\n',
193	      ]);
194	
195	      final cubit = sl<ChatCubit>();
196	      await cubit.init();
197	      expect(cubit.state, isA<ChatReady>());
198	
199	      await cubit.sendMessage('Oi, bom dia!');
200	
201	      final state = cubit.state as ChatReady;
202	      expect(state.sessionId, 'session-1');
203	      expect(state.isSending, isFalse);
204	      expect(state.messages, hasLength(2));
205	      expect(state.messages[0].role, ChatMessageRole.user);
206	      expect(state.messages[0].content, 'Oi, bom dia!');
207	      expect(state.messages[0].status, ChatMessageStatus.complete);
208	      expect(state.messages[1].role, ChatMessageRole.assistant);
209	      expect(state.messages[1].content, 'Olá, tudo bem? Vamos conversar.');
210	      expect(state.messages[1].status, ChatMessageStatus.complete);
211	
212	      expect(adapter.requests, hasLength(4));
213	      final sendRequest = adapter.requests.last;
214	      expect(
215	        sendRequest.path,
216	        sl<UrlBuilder>().build('chat-messages-send', ['session-1']),
217	      );
218	      expect(sendRequest.data, {'content': 'Oi, bom dia!'});
219	      expect(sendRequest.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
220	      expect(
221	        sendRequest.headers['Authorization'],
222	        'Bearer e2e-test-access-token',
223	      );
224	
225	      // The real write-through happened against the real `chat_sessions`
226	      // Hive box (`createSession()`'s own persist-then-return step).
227	      final sessionsBox = sl<Box<Map>>(instanceName: 'chat_sessions');
228	      expect(sessionsBox.get('session-1'), isNotNull);
229	    },
230	  );
231	
232	  test(
233	    'mid-stream drop: a connection that closes with no done/error event '
234	    'keeps the AI bubble\'s partial text (never cleared) and marks it '
235	    'failed, with no exception escaping the cubit',
236	    () async {
237	      adapter.queueJsonResponse(200, {
238	        'data': [_sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z')],
239	      });
240	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
241	      adapter.queueSseResponse([
242	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n'
243	            'event: token\ndata: {"delta":"Entendo."}\n\n',
244	        // Stream ends here with no `done`/`error` event — a mid-stream
245	        // drop (I/O matrix).
246	      ]);
247	
248	      final cubit = sl<ChatCubit>();
249	      await cubit.init();
250	
251	      await cubit.sendMessage('Como você está?');
252	
253	      final state = cubit.state as ChatReady;
254	      expect(state.isSending, isFalse);
255	      expect(state.messages, hasLength(2));
256	      expect(state.messages[1].content, 'Entendo.');
257	      expect(state.messages[1].status, ChatMessageStatus.failed);
258	    },
259	  );
260	
261	  test(
262	    'in-band error event: an SSE `error` event with a taxonomy code marks '
263	    'the AI bubble failed and fires exactly one POST (chat-messages-send '
264	    'is excluded from transparent retry)',
265	    () async {
266	      adapter.queueJsonResponse(200, {
267	        'data': [_sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z')],
268	      });
269	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
270	      adapter.queueSseResponse([
271	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n'
272	            'event: error\ndata: {"code":"RATE_LIMITED","message":"Limite atingido."}\n\n',
273	      ]);
274	
275	      final cubit = sl<ChatCubit>();
276	      await cubit.init();
277	
278	      await cubit.sendMessage('Mais uma pergunta.');
279	
280	      final state = cubit.state as ChatReady;
281	      expect(state.isSending, isFalse);
282	      expect(state.messages[1].content, '');
283	      expect(state.messages[1].status, ChatMessageStatus.failed);
