11	/// The chat feature's one remote data source — non-streaming calls go
12	/// through `ApiClient`'s plain JSON methods exactly like
13	/// `EntriesRemoteDataSource`'s own `create`/`list`/`get`; [sendMessage]
14	/// alone goes through `ApiClient.postStream` and owns the one piece of
15	/// SSE-specific logic this story introduces: splitting the raw byte
16	/// stream into `event:`/`data:` blocks and mapping each into a
17	/// [ChatStreamEvent] (or an in-band [Failure]) — kept feature-local per
18	/// the Code Map, `ApiClient` itself knows nothing about the SSE grammar.
19	class ChatRemoteDataSource {
20	  ChatRemoteDataSource(this._apiClient);
21	
22	  final ApiClient _apiClient;
23	
24	  Future<Either<Failure, List<ChatSessionDto>>> listSessions() async {
25	    final result = await _apiClient.get('chat-sessions-list');
26	    return result.flatMap((json) {
27	      try {
28	        final data = json['data'] as List<dynamic>;
29	        // Review fix: one malformed item is skipped rather than
30	        // discarding every other valid session in the response — same
31	        // per-item isolation the offline-cache fallback already applies.
32	        final dtos = <ChatSessionDto>[];
33	        for (final item in data) {
34	          try {
35	            dtos.add(ChatSessionDto.fromJson(item as Map<String, dynamic>));
36	          } catch (_) {
37	            // Skip this one malformed item.
38	          }
39	        }
40	        // Review fix: a non-empty response where every item failed to
41	        // decode is a parse failure, not "zero sessions" — returning
42	        // `right([])` here would make `ChatCubit._bootstrap()` believe
43	        // none exist and spuriously `createSession()`, hiding the user's
44	        // real sessions behind a new empty one.
45	        if (data.isNotEmpty && dtos.isEmpty) {
46	          return left(
47	            Failure.malformedResponse(
48	              message: 'All items in listSessions() response failed to decode',
49	            ),
50	          );
51	        }
52	        return right(dtos);
53	      } catch (error) {
54	        // A 200 response that doesn't match the expected shape at all
55	        // (e.g. `data` itself isn't a list) is a client-side parse
56	        // failure, never a backend-sent code — same RNF09 rationale
57	        // `EntriesRemoteDataSource`'s own calls document.
58	        return left(Failure.malformedResponse(message: error.toString()));
59	      }
60	    });
61	  }
62	
63	  /// Sends no `title` (Boundaries: "`chat-sessions-create` with no
64	  /// title") — the contract's own `title` field is optional
65	  /// (`openapi.yaml`), an empty body is valid.
66	  Future<Either<Failure, ChatSessionDto>> createSession() async {
67	    final result = await _apiClient.post('chat-sessions-create', data: const {});
68	    return result.flatMap((json) {
69	      try {
70	        final data = json['data'] as Map<String, dynamic>;
71	        return right(ChatSessionDto.fromJson(data));
72	      } catch (error) {
73	        return left(Failure.malformedResponse(message: error.toString()));
74	      }
75	    });
76	  }
77	
78	  Future<Either<Failure, List<ChatMessageDto>>> listMessages(
79	    String sessionId,
80	  ) async {
81	    final result = await _apiClient.get(
82	      'chat-messages-list',
83	      pathParams: [sessionId],
84	    );
85	    return result.flatMap((json) {
86	      try {
87	        final data = json['data'] as List<dynamic>;
88	        // Review fix: one malformed item is skipped rather than
89	        // discarding every other valid message in the response — same
90	        // per-item isolation the offline-cache fallback already applies.
91	        final dtos = <ChatMessageDto>[];
92	        for (final item in data) {
93	          try {
94	            dtos.add(ChatMessageDto.fromJson(item as Map<String, dynamic>));
95	          } catch (_) {
96	            // Skip this one malformed item.
97	          }
98	        }
99	        // Review fix: same "all items malformed" rationale as
100	        // listSessions() above — a non-empty response that fully fails
101	        // to decode must never be mistaken for "no messages", or a
102	        // session's whole history would silently render empty.
103	        if (data.isNotEmpty && dtos.isEmpty) {
104	          return left(
105	            Failure.malformedResponse(
106	              message: 'All items in listMessages() response failed to decode',
107	            ),
108	          );
109	        }
110	        return right(dtos);
111	      } catch (error) {
112	        return left(Failure.malformedResponse(message: error.toString()));
113	      }
114	    });
115	  }
116	
117	  /// Consumes `ApiClient.postStream('chat-messages-send', pathParams:
118	  /// [sessionId], data: {'content': content})` chunk by chunk, buffering
119	  /// raw text until a full `\n\n`-terminated SSE event block is
120	  /// available, then hands each complete block to [_parseEvent].
121	  ///
122	  /// Terminal handling (Design Notes/I/O matrix):
123	  /// - An upstream `Left` (an offline/timeout/etc. failure from the
124	  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
125	  ///   forwarded as-is and ends the stream immediately — covers "Send
126	  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
127	  ///   queued) and any other transport-level failure.
128	  /// - A parsed `done` event or an in-band `error` event (mapped via
129	  ///   [Failure.fromCode]) both end the stream right after being emitted
130	  ///   — the backend's own SSE ordering guarantees neither is followed by
131	  ///   anything else worth reading.
132	  /// - If the underlying byte stream simply ends (no exception, no
133	  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
134	  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
135	  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
136	  ///   (Design Notes).
137	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
138	    String sessionId,
139	    String content,
140	  ) async* {
141	    var buffer = '';
142	    await for (final chunkResult in _apiClient.postStream(
143	      'chat-messages-send',
144	      pathParams: [sessionId],
145	      data: {'content': content},
146	    )) {
147	      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
148	      if (upstreamFailure != null) {
149	        yield left(upstreamFailure);
150	        return;
151	      }
152	      final chunk = chunkResult.fold((_) => '', (s) => s);
153	      // Normalize after concatenation, not per-chunk — a `\r\n` line
154	      // ending split exactly across two chunks (one ends `\r`, the next
155	      // starts `\n`) would otherwise survive unnormalized in `buffer`.
156	      buffer = (buffer + chunk).replaceAll('\r\n', '\n');
157	
158	      var separatorIndex = buffer.indexOf('\n\n');
159	      while (separatorIndex != -1) {
160	        final rawEvent = buffer.substring(0, separatorIndex);
161	        buffer = buffer.substring(separatorIndex + 2);
162	        if (rawEvent.trim().isNotEmpty) {
163	          final parsed = _parseEvent(rawEvent);
164	          if (parsed != null) {
165	            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
166	            final isFailure = parsed.isLeft();
167	            yield parsed;
168	            // A `done`/in-band-error exit is a clean terminal event, not
169	            // a drop — return directly, skipping the trailing
170	            // mid-stream-drop failure below.
171	            if (isDone || isFailure) {
172	              return;
173	            }
174	          }
175	        }
176	        separatorIndex = buffer.indexOf('\n\n');
177	      }
178	    }
179	    // Reached only if the byte stream ended on its own (no exception, no
180	    // `done`/`error` event ever parsed) — a mid-stream drop.
181	    yield left(
182	      const Failure.networkTimeout(
183	        message: 'Connection closed before the response completed',
184	      ),
185	    );
186	  }
187	
188	  /// Parses one complete, blank-line-delimited SSE event block into a
189	  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
190	  /// when the block should simply be skipped — a `context` event
191	  /// (Boundaries: "received and discarded", never surfaced as a
192	  /// [ChatStreamEvent]) or any event name this client doesn't recognize
193	  /// (forward-compatible: an unknown future event type is ignored rather
194	  /// than treated as malformed). Any JSON-decode failure, or a decoded
195	  /// payload missing the field a known event name requires, maps to
196	  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
197	  /// parse as expected becomes `Failure.malformedResponse`, never a
198	  /// crash") — never a thrown exception escaping into [sendMessage]'s own
199	  /// `async*` body.
200	  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
201	    String? eventName;
202	    final dataLines = <String>[];
203	    for (final line in rawEvent.split('\n')) {
204	      if (line.startsWith('event:')) {
205	        eventName = line.substring('event:'.length).trim();
206	      } else if (line.startsWith('data:')) {
207	        var value = line.substring('data:'.length);
208	        if (value.startsWith(' ')) {
209	          value = value.substring(1);
210	        }
211	        dataLines.add(value);
212	      }
213	    }
214	    if (eventName == null) {
215	      return null;
216	    }
217	    final dataStr = dataLines.join('\n');
218	
219	    switch (eventName) {
220	      case 'message_created':
221	        try {
222	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
223	          return right(ChatMessageCreatedEvent(json['id'] as String));
224	        } catch (error) {
225	          return left(
226	            Failure.malformedResponse(
227	              message: 'malformed message_created event: $error',
228	            ),
229	          );
230	        }
231	      case 'context':
232	        // Boundaries: "never rendering the SSE `context` event's
233	        // retrieval/citation data" — received and discarded.
234	        return null;
235	      case 'token':
236	        try {
237	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
238	          return right(ChatTokenEvent(json['delta'] as String));
239	        } catch (error) {
240	          return left(
241	            Failure.malformedResponse(
242	              message: 'malformed token event: $error',
243	            ),
244	          );
245	        }
246	      case 'done':
247	        return right(const ChatDoneEvent());
248	      case 'error':
249	        try {
250	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
251	          final code = json['code'] as String;
252	          final message = json['message'];
253	          return left(
254	            Failure.fromCode(
255	              code,
256	              message is String ? message : 'Unknown error',
257	            ),
258	          );
259	        } catch (error) {
260	          return left(
261	            Failure.malformedResponse(
